document.querySelectorAll('[data-lab="CP03-I1"]').forEach(root=>{const z=root.dataset.lang==='zh',get=n=>root.querySelector('[data-field="'+n+'"]');
function draw(){const n=+get('count').value,b=+get('step').value,M=2000;let seed=31415926;const rand=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return(seed+.5)/4294967296;};let rs=[],sumR2=0,sumG2=0,first=[];
for(let j=0;j<M;j++){let x=0,y=0,zz=0,sx=0,sy=0,sz=0,ss=0;if(j===0)first=[[0,0,0]];for(let i=0;i<n;i++){let h=2*rand()-1,a=2*Math.PI*rand(),q=Math.sqrt(1-h*h);x+=b*q*Math.cos(a);y+=b*q*Math.sin(a);zz+=b*h;sx+=x;sy+=y;sz+=zz;ss+=x*x+y*y+zz*zz;if(j===0)first.push([x,y,zz]);}let r2=x*x+y*y+zz*zz;rs.push(Math.sqrt(r2));sumR2+=r2;sumG2+=ss/(n+1)-(sx*sx+sy*sy+sz*sz)/(n+1)**2;}
const rms=b*Math.sqrt(n),rg=b*Math.sqrt(n*(n+2)/(6*(n+1))),max=Math.max(...rs,2.8*rms),bins=28,dx=max/bins,counts=Array(bins).fill(0);rs.forEach(r=>counts[Math.min(bins-1,Math.floor(r/dx))]++);const density=r=>4*Math.PI*r*r*(3/(2*Math.PI*n*b*b))**1.5*Math.exp(-3*r*r/(2*n*b*b));let ymax=Math.max(...counts.map(c=>c/(M*dx)),...Array.from({length:101},(_,i)=>density(max*i/100)))*1.12;
const text=(x,y,s,n=19)=>'<text x="'+x+'" y="'+y+'" font-family="sans-serif" font-size="'+n+'" fill="#193e45">'+s+'</text>';
let s='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 690" role="img" aria-label="'+(z?'三维链的投影及末端距分布':'Projected three-dimensional chain and distance distribution')+'"><rect width="600" height="690" fill="#f4f1e8"/>'+text(55,30,z?'一条样本链：xy 平面投影':'One sampled chain: projection onto xy',21);
let extent=Math.max(...first.flatMap(a=>[Math.abs(a[0]),Math.abs(a[1])]),rms)*1.15,sc=105/extent;
s+='<path d="M65 170H550 M300 55V285" stroke="#ccd6cd"/>';s+='<polyline points="'+first.map(a=>(300+a[0]*sc).toFixed(2)+','+(170-a[1]*sc).toFixed(2)).join(' ')+'" fill="none" stroke="#148579" stroke-width="2.5"/>';
let last=first[first.length-1];s+='<circle cx="300" cy="170" r="5" fill="#bd7943"/><circle cx="'+(300+last[0]*sc)+'" cy="'+(170-last[1]*sc)+'" r="5" fill="#173b43"/>'+text(65,312,z?'坐标十字位于链起点；图中长度标尺：':'Axes cross at the chain start; scale bar:',18);
let bar=rms/2;s+='<path d="M70 337h'+(bar*sc)+'" stroke="#193e45" stroke-width="3"/>'+text(85+bar*sc,343,bar.toFixed(2)+' nm',18);
s+=text(55,388,z?'2000 条链的距离分布':'Distance distribution of 2000 chains',21);
for(let i=0;i<bins;i++){let h=counts[i]/(M*dx)/ymax*190;s+='<rect x="'+(65+i*480/bins)+'" y="'+(600-h)+'" width="'+(480/bins-1)+'" height="'+h+'" fill="#a8cfc0"/>';}
s+='<polyline points="'+Array.from({length:121},(_,i)=>{let r=max*i/120;return(65+i*4)+','+(600-density(r)/ymax*190)}).join(' ')+'" fill="none" stroke="#bd7943" stroke-width="3"/>'+text(65,625,'0')+text(500,625,max.toFixed(1))+text(235,650,z?'末端距 R / nm':'End-to-end R / nm',20)+text(65,678,z?'柱：样本；线：高斯径向密度（nm⁻¹）':'Bars: samples; line: Gaussian radial density (nm⁻¹)',18)+text(12,420,ymax.toFixed(2),16);
get('plot').innerHTML=s;get('values').textContent='N = '+n+'; b = '+b.toFixed(1)+' nm; '+(z?'轮廓长度 ':'contour length ')+(n*b).toFixed(1)+' nm';get('result').textContent=(z?'均方根末端距：样本 ':'Rms end-to-end distance: sample ')+Math.sqrt(sumR2/M).toFixed(3)+(z?'，理论 ':'; theory ')+rms.toFixed(3)+' nm. '+(z?'回转半径平方平均后开方：样本 ':'Square root of mean-square gyration radius: sample ')+Math.sqrt(sumG2/M).toFixed(3)+(z?'，有限链理论 ':'; finite-chain theory ')+rg.toFixed(3)+' nm.';}
get('count').addEventListener('input',draw);get('step').addEventListener('input',draw);get('reset').addEventListener('click',()=>{get('count').value='100';get('step').value='1';draw();});draw();});